 const available=cell=>choices.filter(color=>!neighbors(cell).some(([y,x])=>board[y][x]?.color===color));
 const freshOrders=cells.map(()=>shuffle([...choices],random));
 function solve(extra=[]){
  const variables=[...cells,...extra],original=extra.map(([r,c])=>board[r][c].color);
  for(const [r,c] of variables)board[r][c].color=-1;
  const orders=[...freshOrders,...original.map(color=>[color,...choices.filter(c=>c!==color)])];let budget=12000;
  function place(left){
   if(!left)return true;if(--budget<=0)return false;
   let best=-1,options=null;
   for(let i=0;i<variables.length;i++){
    const [r,c]=variables[i];if(board[r][c].color>=0)continue;
    const colors=available(variables[i]);if(!colors.length)return false;
    if(!options||colors.length<options.length){best=i;options=colors;if(colors.length===1)break;}
   }
   const [r,c]=variables[best];
   for(const color of orders[best])if(options.includes(color)){
    board[r][c].color=color;if(place(left-1))return true;
   }
   board[r][c].color=-1;return false;
  }
  if(place(variables.length))return extra.filter(([r,c],i)=>board[r][c].color!==original[i]);
  extra.forEach(([r,c],i)=>board[r][c].color=original[i]);
  cells.forEach(([r,c])=>board[r][c].color=-1);return null;
 }
 const plain=solve();if(plain)return plain;
 if(colorCount!==3)throw new Error('補充する色を決められませんでした');
 // Three-color debug boards can have an impossible fixed-color boundary.
 // First try changing exactly one neighboring cookie; keep numbers/items attached.
 const frontier=new Map();
 for(const cell of cells)for(const p of neighbors(cell))if(!freshKeys.has(p[0]*SIZE+p[1]))frontier.set(p[0]*SIZE+p[1],p);
 const rank=([r,c])=>board[r][c].step?3:board[r][c].special?2:board[r][c].number!=null?1:0;
 const edge=[...frontier.values()].sort((a,b)=>rank(a)-rank(b));
 for(const cell of edge){const fixed=solve([cell]);if(fixed)return fixed;}
 // Only expand the editable boundary if no single-cookie correction works.
 const region=[...edge],added=new Set([...freshKeys,...frontier.keys()]);
 for(let i=0;i<region.length;i++){
  const fixed=solve(region);if(fixed)return fixed;
  for(const p of neighbors(region[i])){const k=p[0]*SIZE+p[1];if(!added.has(k)){added.add(k);region.push(p);}}
 }
