 x.fillStyle=metal;x.strokeStyle=m.dark;x.lineWidth=1.1;x.beginPath();x.roundRect(-11,-20,22,11,4);x.fill();x.stroke();x.shadowBlur=0;x.shadowOffsetY=0;
