 for(const side of [-1,1]){x.fillStyle=m.rim;x.beginPath();x.arc(side*9,-11,2,0,Math.PI*2);x.fill();}
 x.fillStyle=metal;x.beginPath();x.roundRect(-14,-9,28,5,2);x.fill();x.stroke();
