 x.beginPath();x.moveTo(-12,-4);x.lineTo(12,-4);x.lineTo(9,6);x.lineTo(5,14);x.lineTo(0,21);x.lineTo(-5,14);x.lineTo(-9,6);x.closePath();x.fill();x.stroke();
