  for(let row=-1;row<4;row++){const y=row*8-3+shift;x.fillStyle=row%2?'#eaffff':'#82caff';x.beginPath();x.moveTo(-13,y);x.lineTo(1,y+6);x.lineTo(12,y-2);x.lineTo(2,y-6);x.closePath();x.fill();x.strokeStyle='#ffffffce';x.lineWidth=.7;x.stroke();}
