  for(let row=-2;row<5;row++){const y=row*8+shift;x.strokeStyle=m.dark;x.lineWidth=4;x.beginPath();x.moveTo(-15,y+5);x.quadraticCurveTo(-1,y+3,15,y-5);x.stroke();x.strokeStyle=m.light;x.lineWidth=1.6;x.beginPath();x.moveTo(-15,y+3);x.quadraticCurveTo(-1,y+1,15,y-7);x.stroke();}
