 if(typeof sceneCountSound==='function')sceneCountSound(s,'scale-tick',s.chocoAwardPhase==='add'?s.chocoWinValue:s.chocoAwardValue,e.version+'/'+s.chocoAwardPhase,s.i===active&&s.chocoWinCounting);
