 x.fillStyle='#fff0c9';for(const [cx,cy,r] of [[74,42,3],[246,42,2],[66,276,2.5],[252,286,3],[20,118,2],[300,196,2]]){x.beginPath();x.arc(cx,cy,r,0,Math.PI*2);x.fill();}
 x.restore();
