sixArtLogoMarkup=function(){return '<img class="six-art-logo" src="assets/six-drop-title-v2.webp" alt="シックスドロップ SIX DROP">';};
const sixDropOriginalStageEffects=sixStageEffects;
sixStageEffects=function(x,fx,p,round,rows,reduced){sixDropOriginalStageEffects(x,fx,p,round,rows,reduced);if(fx?.phase!=='pyramidShape'||!fx.forms?.length||reduced)return;for(const f of fx.forms){const ps=f.cells.map(c=>sixXY(...c,rows)),cx=ps.reduce((v,z)=>v+z.x,0)/ps.length,cy=ps.reduce((v,z)=>v+z.y,0)/ps.length;x.save();x.strokeStyle='#fff8ba';x.lineWidth=2;x.globalAlpha=(1-p)*.8;for(let k=0;k<9;k++){const yy=cy-32+k*8;x.beginPath();x.moveTo(cx-90+85*p,yy);x.lineTo(cx-45+85*p,yy);x.stroke();}x.restore();}};

// Cabinet accents are presentation-only and use the existing paused visual clock.
function sixArcadeCounter(s){
 const e=s.engine,el=$('carnival-win');if(!el||!e)return;
 const target=medalWin(app.bet(s.i),e.totalHundredths),t=s.sixWinTween;
 let value=target;
 if(t&&t.version===e.version&&t.to===target&&!motionReduced){const p=Math.max(0,Math.min(1,((s.candyTime||0)-t.start)/650));value=Math.floor(t.from+(t.to-t.from)*(1-Math.pow(1-p,3)));if(p===1)s.sixWinTween=null;}
 sceneCountSound(s,'six-count',value,e.version,s.i===active&&!!t);
 if(el.textContent!==num(value))fitGoldenNumber(el,num(value),23,100);el.setAttribute('aria-label','TOTAL WIN '+num(target));s.sixDisplayedWin=value;
}
function sixArcadeAccents(s,x,time){
 sixArcadeCounter(s);const e=s.engine,celebration=s.sixClearAccent,age=celebration&&celebration.version===e.version?time-celebration.start:2000,clear=age>=0&&age<1200;
 s.sixHeading?.classList.toggle('six-clear-flash',clear&&!motionReduced);
 if(!app.bet(s.i))return;
 x.save();const hue=[168,66,35,340,280][Math.max(0,Math.min(4,e.roundIndex-1))];
 // Small lamps stay outside the playable tray.
 for(let k=0;k<14;k++)for(const side of [0,1]){const y=24+k*21,pulse=motionReduced?.35:.3+.7*Math.pow(.5+.5*Math.sin(time/260-k*.65+side*1.4),3);x.globalAlpha=.3+.5*pulse;x.fillStyle='hsl('+hue+' 90% '+(65+pulse*25)+'%)';x.shadowColor=x.fillStyle;x.shadowBlur=3+pulse*3;x.beginPath();x.arc(side?314:6,y,1.6+pulse*.5,0,Math.PI*2);x.fill();}
 if(clear&&!motionReduced){const p=age/1200;x.shadowBlur=0;for(let k=0;k<24;k++){const side=k%2,delay=(k%6)*.025,u=Math.max(0,p-delay),cx=side?310:10,cy=30+u*240+(k%6)*19;x.globalAlpha=Math.max(0,(1-p)*.85);x.save();x.translate(cx+Math.sin(k*2.3+u*9)*6,cy);x.rotate(k+u*7);x.fillStyle=['#ffe7a1','#ffafd6','#b7f3e1'][k%3];x.fillRect(-2,-3,4,6);x.restore();}}
 x.restore();
}
const sixArcadeBaseEvent=carnivalEvent;
carnivalEvent=function(s,ev,e,a){
 if(ev.phase==='ready'||ev.phase==='error'){s.sixWinTween=null;s.sixDisplayedWin=0;s.sixClearAccent=null;s.sixHeading?.classList.remove('six-clear-flash');}
 sixArcadeBaseEvent(s,ev,e,a);
 if(['pyramidAward','pyramidRoundBonus','pyramidAllClear'].includes(ev.phase)&&ev.gain>0){const target=medalWin(a.bet(s.i),e.totalHundredths);s.sixWinTween={version:e.version,from:Math.min(target,s.sixDisplayedWin??medalWin(a.bet(s.i),Math.max(0,e.totalHundredths-ev.gain))),to:target,start:s.candyTime||0};}
 if(ev.phase==='pyramidRoundBonus'){s.sixClearAccent={version:e.version,start:s.candyTime||0};if(s.i===active)sixCandyAudio('clear');}
};
const sixArcadeBaseHud=carnivalHud;
carnivalHud=function(a){sixArcadeBaseHud(a);const s=slots[2];if(s?.engine?.kind==='candy')sixArcadeCounter(s);};

function sixCandyPromotionMarkup(round){
 const title='ROUND '+round;
 return '<svg class="six-promotion-sign" viewBox="0 0 280 94" role="img" aria-label="ラウンド'+round+'進出"><title>NEXT ROUND '+round+'・次ラウンドへ！</title><defs><pattern id="six-prom-stripes" width="18" height="18" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="18" height="18" fill="#fff8e9"/><rect width="8" height="18" fill="#ff75ad"/></pattern><linearGradient id="six-prom-face" x2="0" y2="1"><stop stop-color="#fffce6"/><stop offset="1" stop-color="#ffc8e6"/></linearGradient></defs><g stroke-linejoin="round"><path d="M24 26 3 15 8 47 3 77 27 67M256 26 277 15 272 47 277 77 253 67" fill="url(#six-prom-stripes)" stroke="#aa3b79" stroke-width="3"/><rect x="20" y="5" width="240" height="84" rx="30" fill="url(#six-prom-stripes)" stroke="#a53a74" stroke-width="4"/><rect x="28" y="13" width="224" height="68" rx="24" fill="url(#six-prom-face)" stroke="#ffe99f" stroke-width="4"/><path d="M48 23Q140 5 232 23" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round"/><path d="'+sixPromotionPaths[round]+'" transform="translate(0 2)" fill="#f75c9e" stroke="#82366a" stroke-width="6"/><path d="'+sixPromotionPaths[round]+'" fill="#f75c9e" stroke="#fffcec" stroke-width="2.5" paint-order="stroke fill"/><path d="'+sixPromotionSubtitle+'" fill="#8a326c" stroke="#fffaf0" stroke-width="3"/><path d="'+sixPromotionSubtitle+'" fill="#8a326c"/><g fill="#fff5a7" stroke="#d89b42"><path d="m36 39 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1Z"/><path d="m244 39 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1Z"/></g></g></svg>';
}
const sixCandySignBaseEvent=carnivalEvent;
carnivalEvent=function(s,ev,e,a){
 sixCandySignBaseEvent(s,ev,e,a);
 if(ev.phase==='ready'||ev.phase==='error'){s.sixPromotionShown=new Set();s.candyReward.classList.remove('six-candy-promotion','six-simple-award');}
 if(['pyramidAward','pyramidRoundBonus','pyramidAllClear'].includes(ev.phase)&&!s.candyReward.hidden){
  const key=e.version+'/'+e.roundIndex,next=s.candyReward.querySelector('.six-next'),advance=next?.textContent.startsWith('NEXT ROUND');s.sixPromotionShown??=new Set();
  const simple=s.sixPromotionShown.has(key);if(!simple)s.candyReward.removeAttribute('aria-label');s.candyReward.classList.toggle('six-simple-award',simple);s.candyReward.classList.toggle('six-candy-promotion',!simple&&!!advance);
  if(simple){s.candyReward.innerHTML='<strong>＋'+num(medalWin(a.bet(s.i),ev.gain))+' <em>WIN</em></strong>';s.candyReward.setAttribute('aria-label','配当増加 '+num(medalWin(a.bet(s.i),ev.gain))+' WIN');}
  else if(advance){s.sixPromotionShown.add(key);next.innerHTML=sixCandyPromotionMarkup(e.roundIndex+1);}
 }
};

/* Rare shapes: deterministic, phase-bound jewels; never modify the board. */
const sixRareBaseEffects=sixStageEffects;
sixStageEffects=function(x,fx,p,round,rows,reduced){
 if(reduced&&fx?.phase==='pyramidShape'&&fx.forms?.some(f=>f.type!=='line'))p=.5;
 sixRareBaseEffects(x,fx,p,round,rows,reduced);
 if(!fx||!['pyramidShape','pyramidAward'].includes(fx.phase))return;
 for(const form of fx.forms||[]){
  if(form.type==='line')continue;
  const hex=form.type==='hexagon',ps=form.cells.map(c=>sixXY(...c,rows)),cx=ps.reduce((n,z)=>n+z.x,0)/ps.length,cy=ps.reduce((n,z)=>n+z.y,0)/ps.length,hull=sixHull(ps),award=fx.phase==='pyramidAward',u=reduced?.5:p;
  x.save();x.lineJoin='round';x.globalAlpha=award?Math.max(0,1-p):.85;x.shadowBlur=reduced?0:14;x.shadowColor=hex?'#eeb8ff':'#ffd36a';
  // Layered gem silhouette remains centered on the actual matching drops.
  for(const [scale,width,color] of [[1.22,5,hex?'#b463df':'#d58a21'],[1.12,3,'#fff4b6'],[1,2,'#ffffff']]){
   x.strokeStyle=color;x.lineWidth=width;x.beginPath();hull.forEach((v,i)=>{const xx=cx+(v.x-cx)*scale,yy=cy+(v.y-cy)*scale;i?x.lineTo(xx,yy):x.moveTo(xx,yy);});x.closePath();x.stroke();
  }
  if(!reduced){
   const count=hex?24:15;
   for(let k=0;k<count;k++){
    const a=k*Math.PI*2/count+u*(hex?1.1:-.7),radius=35+(award?u*65:14*Math.sin(u*Math.PI))+(k%3)*8,xx=cx+Math.cos(a)*radius,yy=cy+Math.sin(a)*radius;
    const color=hex?['#ffaadf','#ffe48d','#a5f5eb','#c8b5ff'][k%4]:'#ffe28e';
    sixArtStar(x,xx,yy,2+(k%3), '#fffbea',color);
    x.strokeStyle=color;x.lineWidth=1.3;x.beginPath();x.moveTo(cx+Math.cos(a)*(radius-10),cy+Math.sin(a)*(radius-10));x.lineTo(xx,yy);x.stroke();
   }
  }
  x.restore();
 }
};

class Arcade{
 constructor({random=Math.random,sleep=ms=>new Promise(r=>setTimeout(r,ms)),onEvent=()=>{},onChange=()=>{},speed=1.4,colorCount=5}={}){
  Object.assign(this,{random,sleep,onEvent,onChange,speed,credit:1000,displayCredit:1000,totalWin:0,wonderSteps:0,wonderValue:0,wonderBank:[],roundWins:[0,0,0],payout:null,result:null,fastForward:false,debug:true,bets:[3000,3000,3000],locked:[0,0,0],paid:[false,false,false],enabled:[true,true,true],draws:[],phase:'ready',paused:false,token:0,dealing:false});
  this.colorCount=[3,4,5].includes(colorCount)?colorCount:5;this.engines=[];
  for(let i=0;i<3;i++)this.engines.push(new (i===1?ChocoDigEngine:i===2?CandyCarnivalEngine:Engine)({random,sleep,speed,colorCount:this.colorCount,onEvent:(ev,e)=>{
   if(ev.phase==='stepcollect'&&this.phase==='playing'&&this.enabled[i]){this.wonderBank.push(...ev.steps.map(step=>{return {...step,game:i};}));this.wonderSteps=this.wonderBank.length;this.wonderValue+=ev.steps.reduce((n,step)=>n+step.value,0);}
   if(ev.phase==='complete'&&!this.paid[i]&&this.enabled[i]&&this.phase==='playing'){
    this.paid[i]=true;this.roundWins[i]=medalWin(this.locked[i],e.totalHundredths);
    if(this.enabled.every((yes,j)=>!yes||this.paid[j]))this.finishRound();
   }
   if(ev.phase==='error'){this.phase='error';this.token++;this.dealing=false;this.drawSource?.pause(true);}
   this.onEvent(i,ev,e,this);
  }}));
 }
 setColorCount(count){
  if(this.phase!=='ready'||![3,4,5].includes(count))return false;
  if(count===this.colorCount)return true;
  this.colorCount=count;
  for(const e of this.engines){e.colorCount=count;e.reset({keepWonder:true,keepHammers:false});}
  this.onChange(this);return true;
 }
 get wonderReady(){return this.wonderBank.length>=5;}
 setBet(i,n){if(this.phase!=='ready'||!Number.isSafeInteger(n)||n<0)return false;this.bets[i]=n;this.onChange(this);return true;}
 start(){
  if(this.phase!=='ready'||!this.bets.some(n=>n>0)||this.drawSource?.ready===false)return false;
  this.debugRainbowIssued=false;this.enabled=this.bets.map(n=>n>0);this.locked=[...this.bets];this.paid=[false,false,false];this.roundWins=[0,0,0];this.totalWin=0;this.payout=null;this.result=null;this.fastForward=false;this.engines.forEach(e=>e.presentationRate=1);this.displayCredit=this.credit;this.draws=[];this.phase='playing';this.dealing=true;
  const token=++this.token;
  // Rainbow is decided at round start, and replaces the on-board sugar rather
  // than being awarded automatically when a normal sugar is collected.
  const rainbow=(debugForceRainbowSugar||this.random()<RAINBOW_SUGAR_CHANCE);
  let rainbowBoard=-1;
  if(rainbow&&this.enabled[0]){
   const e=this.engines[0],sugarCells=[],emptyCells=[],otherCells=[];
   for(let r=0;r<SIZE;r++)for(let col=0;col<SIZE;col++){
    const tile=e.board[r][col];
    if(!tile||tile.special)continue;
    if(tile.step)sugarCells.push(tile);
    else if(tile.number==null)emptyCells.push(tile);
    else otherCells.push(tile);
   }
   // Prefer an existing on-board sugar. If none exists, make one usable
   // tile available so the debug guarantee never silently fails.
   const candidates=sugarCells.length?sugarCells:emptyCells.length?emptyCells:otherCells;
   const tile=candidates.length?candidates[Math.floor(this.random()*candidates.length)]:null;
   if(tile){
    if(tile.number!=null)tile.number=null;
    // Keep the original sugar's value and replace only its identity/art.
    const original=e.wonderToken||e.basketState?.[e.wonderColumn]?.pending?.[0];
    const step={id:++e.stepUid,value:original?.value||Math.max(1,this.locked[0]),tier:6,kind:'direct-jpc',directJpc:true};
    for(const row of e.board)for(const t of row)if(t?.step)t.step=null;
    tile.step=step;e.wonderToken=step;e.wonderIssued=true;e.wonderCollected=false;
    const basket=e.basketState[e.wonderColumn];
    if(basket){basket.pending.length=0;basket.remaining=0;}
    this.debugRainbowIssued=true;rainbowBoard=0;
   }
  }
  this.engines.forEach((e,i)=>{e.roundBet=this.locked[i];if(this.enabled[i])e.start();});
  this.onChange(this);
  if(rainbowBoard>=0)this.onEvent(rainbowBoard,{phase:'rainbowappear'},this.engines[rainbowBoard],this);
  if(this.drawSource){try{this.drawSource.start({token,onNumber:n=>this.acceptNumber(n,token),onError:message=>this.failDraw(message,token)});}catch(error){this.failDraw(error.message,token);return false;}}else this.deal(token);return true;
 }
 async wait(ms,token){let remaining=ms;while(remaining>0&&token===this.token){const slice=Math.min(40,remaining);await this.sleep(slice);if(!this.paused)remaining-=slice;}return token===this.token;}
 acceptNumber(n,token){
  if(token!==this.token||this.phase!=='playing'||this.paused||this.draws.length>=8||!Number.isInteger(n)||n<1||n>25||this.draws.includes(n))return false;
  this.draws.push(n);this.engines.forEach((e,i)=>{if(this.enabled[i])e.previewDraw(n);});
  // Submit one atomic batch after ball 3 / 5; previewed cells never resolve early.
  const count=this.draws.length,release=count===3?this.draws.slice(0,3):count===5?this.draws.slice(3,5):count>5?[n]:[];
  this.engines.forEach((e,i)=>{if(!this.enabled[i])return;const values=e.drawMode==='single'?[n]:release;if(values.length)e.enqueueBatch(values);});
  if(this.draws.length===8){this.dealing=false;this.boostAfterDraws(token);}this.onChange(this);return true;
 }
 failDraw(message,token){if(token!==this.token||this.phase!=='playing')return;this.drawError=message;this.phase='error';this.token++;this.dealing=false;this.pause(true);this.onChange(this);}
 async deal(token){
  for(let k=0;k<8;k++){
   if(k&&!await this.wait(5000,token))return;
   if([3,5,6,7].includes(k))while(token===this.token&&this.phase==='playing'&&!this.engines.every((e,i)=>!this.enabled[i]||(!e.opening&&e.idle&&e.processed>=e.accepted)))await this.sleep(40);
   while(this.paused&&token===this.token)await this.sleep(40);
   if(token!==this.token||this.phase!=='playing')return;
   const pool=Array.from({length:25},(_,i)=>i+1).filter(n=>!this.draws.includes(n));
   if(!this.acceptNumber(pool[Math.floor(this.random()*pool.length)],token))return;
  }
 }
 async boostAfterDraws(token){
  let remaining=5000;
  while(remaining>0&&token===this.token&&this.phase==='playing'){
   const slice=Math.min(40,remaining);await this.sleep(slice);if(!this.paused)remaining-=slice;
  }
  if(token!==this.token||this.phase!=='playing'||remaining>0)return;
  this.fastForward=true;for(const e of this.engines)e.presentationRate=3;this.onChange(this);
 }
 finishRound(){
  if(this.phase!=='playing')return;
  this.totalWin=this.roundWins.reduce((sum,n)=>sum+n,0);
  this.displayCredit=this.credit;this.payout=null;this.result={elapsed:0,duration:1800};this.phase='result';
  this.onChange(this);
 }
 advanceResult(ms){
  if(this.phase!=='result'||!this.result||this.paused||!Number.isFinite(ms)||ms<=0)return false;
  this.result.elapsed=Math.min(this.result.duration,this.result.elapsed+ms);
  if(this.result.elapsed>=this.result.duration)this.beginPayout();else this.onChange(this);
  return true;
 }
 beginPayout(){
  if(this.phase!=='result')return false;
  const from=this.credit;this.credit+=this.totalWin;this.displayCredit=from;
  // The result is visible first; commit the award exactly once when payout begins.
  this.payout=this.totalWin>0?{from,to:this.credit,amount:this.totalWin,elapsed:0,duration:Math.min(2600,Math.max(1100,700+Math.log2(this.totalWin+1)*110))}:null;
  this.phase=this.payout?'paying':'complete';this.onChange(this);return true;
 }
 advancePayout(ms){
  if(this.phase!=='paying'||!this.payout||this.paused||!Number.isFinite(ms)||ms<=0)return false;
  const p=this.payout;p.elapsed=Math.min(p.duration,p.elapsed+ms);
  const t=p.elapsed/p.duration;
  this.displayCredit=Math.min(p.to,p.from+Math.floor(p.amount*t*(2-t)));
  if(t>=1){this.displayCredit=p.to;this.phase='complete';}
  this.onChange(this);return true;
 }
 pause(value){this.paused=value;for(const e of this.engines)e.paused=value;this.drawSource?.pause(value);}
 prepare(){this.token++;this.drawSource?.reset();this.drawError=null;this.dealing=false;this.displayCredit=this.credit;this.totalWin=0;this.roundWins=[0,0,0];this.payout=null;this.result=null;this.fastForward=false;this.phase='ready';this.paused=false;this.draws=[];this.paid=[false,false,false];this.locked=[0,0,0];this.enabled=this.bets.map(n=>n>0);for(const e of this.engines)e.reset({keepWonder:!this.clearingWonder});this.onChange(this);}
 resetDebug(){this.credit=1000;this.bets=[3000,3000,3000];this.wonderSteps=0;this.wonderValue=0;this.wonderBank=[];this.clearingWonder=true;this.prepare();this.clearingWonder=false;}
 bet(i){return this.phase==='ready'?this.bets[i]:this.locked[i];}
}
// Only the next HIT is simulated. Refill cannot create a link, so no RNG is used.
function copyReachState(e){
 const q=Object.create(Engine.prototype);
 Object.assign(q,{board:e.board.map(row=>row.map(t=>t?{...t,step:t.step?{...t.step}:null}:null)),maxLink:e.maxLink,maxChain:e.maxChain,allClears:e.allClears,totalHundredths:e.totalHundredths,roundSteps:e.roundSteps,roundHammers:e.roundHammers,roundCleared:e.roundCleared,wonderCollected:e.wonderCollected,wonderToken:e.wonderToken,history:[],onEvent:()=>{}});
 return q;
}
const reachTier=(total,allClear)=>allClear?3:total>=1000?2:total>=300?1:0;
function predictNextHit(e,number,pending=[]){
 const q=copyReachState(e),hit=[],numbers=new Set([...pending,number]);let depth=0;
 for(let r=0;r<SIZE;r++)for(let c=0;c<SIZE;c++)if(q.board[r][c]&&numbers.has(q.board[r][c].number))hit.push([r,c]);
 if(!hit.length)return null;
 q.remove(q.resolveLinks([{cells:hit}]).cells);depth=1;q.maxChain=Math.max(q.maxChain,depth);q.gravity();let linked=groups(q.board);
 while(linked.length){
  depth++;q.recordLinks(linked,{depth,number,ball:1});q.remove(q.resolveLinks(linked).cells,{chain:true});q.gravity();linked=groups(q.board);
 }
 const gain=q.totalHundredths-e.totalHundredths,allClear=q.allClears>e.allClears;
 return {number,total:q.totalHundredths,gain,maxLink:q.maxLink,chain:depth,allClear,tier:reachTier(q.totalHundredths,allClear)};
}

// Keep the numeral height and right edge fixed; squeeze horizontally only as needed.
function fitGoldenNumber(el,text,size,width){
 let face=el.querySelector('.gold-number');
 if(!face){el.textContent='';face=document.createElement('span');face.className='gold-number';el.append(face);}
 text=String(text);if(face.textContent!==text)face.textContent=text;
 const ems=Math.max(.6958,payoutWidth(text)),available=Math.max(1,width-2);
 const font=Math.min(size,available/(ems*.55)),scale=Math.min(1,available/(ems*font));
 const key=text+'/'+font+'/'+scale;if(face.dataset.fit!==key){face.dataset.fit=key;face.style.fontSize=font.toFixed(2)+'px';face.style.transform='scaleX('+scale.toFixed(4)+')';face.style.marginLeft=(-(ems*font)*(1-scale)).toFixed(2)+'px';}
 return face;
}

