function traySeams(){
 const paths=[];
 for(let n=1;n<SIZE;n++){
  const v=n*CELL;
  // Soft imperfections in the tin partitions, never another tile background.
  paths.push('M'+v+' 0 Q'+(v-.55)+' 37 '+v+' 74.5 T'+v+' 149 T'+v+' 223.5 T'+v+' 298');
  paths.push('M0 '+v+' Q37 '+(v+.55)+' 74.5 '+v+' T149 '+v+' T223.5 '+v+' T298 '+v);
 }
 const d=paths.join(' ');
 return '<svg class="tray-seams" viewBox="0 0 298 298" aria-hidden="true"><path class="seam-rim" d="'+d+'"/><path class="seam-shadow" d="'+d+'"/></svg>';
}

