 if(plan.sources.length){sceneSound('color-burst',{delay:start});const impact=Math.min(...plan.sources.map(p=>p.strike)),launch=Math.min(...plan.sources.map(p=>p.launch));playHammerImpact(impact);sceneSound('hammer-launch',{delay:launch});}
 // A few grouped impacts follow the visual wave, without a voice for every tile.
