// One finite timer animates only the currently visible game's payout frame.
let payClimbTimer=null;
function stopPayClimb(s){s.payClimb=null;s.payDisplayedLink=null;}
function startPayClimb(s,previous,target,duration){
 stopPayClimb(s);
 if(s.i!==active||motionReduced||target<MIN_PAID_LINK)return;
 const first=Math.max(MIN_PAID_LINK,previous+1),steps=target-first;
 s.payDisplayedLink=first;
 if(steps>0)s.payClimb={target,interval:Math.max(24,Math.min(270,duration*.82/steps)),due:0};
 syncPayClimb();
}
function advancePayClimb(now=Date.now()){
 const s=slots[active],climb=s.payClimb;
 if(!climb||app.paused||document.hidden||!inView||now<climb.due)return;
 s.payDisplayedLink=Math.min(climb.target,s.payDisplayedLink+1);sceneSound('pay-step',{rate:1+Math.min(12,s.payDisplayedLink)*.015});
 if(s.payDisplayedLink>=climb.target){sceneSound('pay-lock');stopPayClimb(s);}else climb.due=now+climb.interval/(s.engine.presentationRate||1);
 scheduleUI(app);
}
function syncPayClimb(){
 if(payClimbTimer!==null)clearTimeout(payClimbTimer);payClimbTimer=null;
 const s=slots[active],climb=s.payClimb;if(!climb)return;
 if(!app||app.paused||document.hidden||!inView){climb.due=0;return;}
 const now=Date.now();if(!climb.due)climb.due=now+climb.interval/(s.engine.presentationRate||1);
 payClimbTimer=setTimeout(()=>{payClimbTimer=null;advancePayClimb();syncPayClimb();},Math.max(16,climb.due-now));
}

const PAY_ROW_HEIGHT=19,PAY_TOP=67;
function updatePayTable(e,bet){
 const shown=slots[active].payDisplayedLink??e.maxLink,track=$('pay'),top=linkRows(shown)[0],key=active+'/'+bet+'/'+shown;
 if(payKey===key)return;payKey=key;track.dataset.hasWin=String(shown>=MIN_PAID_LINK);
 const switched=track.dataset.game!==String(active),first=!track.children.length;
 if(first){
  for(let n=PAY_TOP;n>=2;n--){const row=document.createElement('div');row.className='link-pay-row';row.dataset.link=String(n);row.setAttribute('role','row');row.innerHTML='<span class="link-name" role="rowheader">'+n+' LINK</span><span class="link-award" role="cell"><b class="payout-number"></b><small class="win-word">WIN</small></span>';track.append(row);}
 }
 if(track.dataset.bet!==String(bet))for(const row of track.querySelectorAll('.link-pay-row')){
  const value=num(bet*payoutTenths(Number(row.dataset.link))/10),label=row.querySelector('.payout-number');fitGoldenNumber(label,value,10,34);
 }
 for(const row of track.querySelectorAll('.link-pay-row')){const n=Number(row.dataset.link);row.classList.toggle('chosen',n===shown);row.setAttribute('aria-hidden',String(n>top||n<top-6));}
 const previous=Number(track.dataset.top||top),snap=first||switched||e.phase==='ready'||motionReduced||document.body.classList.contains('minimal');
 track.style.transition=snap?'none':'transform '+Math.min(1250,620+Math.abs(top-previous)*90)+'ms cubic-bezier(.22,.65,.24,1)';
 track.style.transform='translateY('+(-(PAY_TOP-top)*PAY_ROW_HEIGHT)+'px)';
 updateLinkSelection(track,shown,snap);
 track.dataset.top=String(top);track.dataset.game=String(active);track.dataset.bet=String(bet);
 $('pay-window').setAttribute('aria-label','最大LINK配当 '+(top-6)+'から'+top+' LINK、降順');
}

