   for(const [name,value] of [['--supply-start',-timing.distance+'px'],['--supply-delay',timing.release/e.speed+'ms'],['--supply-fall',timing.fall/e.speed+'ms'],['--emerge-time',150/e.speed+'ms'],['--landing-delay',(timing.release+timing.fall)/e.speed+'ms'],['--landing-time',110/e.speed+'ms'],['--spill-angle',angle]])tile.style.setProperty(name,value);
