  const t=(fx.elapsed-source.strike)/190;if(t<0||t>=1)continue;const x=(source.c+.5)*CELL,y=(source.r+.5)*CELL;
  ctx.globalAlpha=1-t;ctx.fillStyle='#fff8c7';ctx.beginPath();ctx.ellipse(x,y+5,8+18*t,4+11*t,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=inks[source.color];ctx.lineWidth=3*(1-t)+1;
  for(let k=0;k<7;k++){const a=k*Math.PI*2/7;ctx.beginPath();ctx.moveTo(x+Math.cos(a)*(5+7*t),y+Math.sin(a)*(5+7*t));ctx.lineTo(x+Math.cos(a)*(12+22*t),y+Math.sin(a)*(12+22*t));ctx.stroke();}
