 if(ev.phase==='queued')return;
 if(ev.phase!=='hammergift'||!animate)stopHammerTransfer(s);
 s.board.classList.toggle('idle',['ready','waiting','settled','complete'].includes(ev.phase));
 if(ev.phase!=='vanish')stopShatter(s);renderChain(s);renderAllClear(s,ev,e,animate);
 const primary=new Set((ev.primaryCells||ev.cells||[]).map(([r,c])=>e.board[r][c]?.id)),remote=new Set((ev.remoteCells||[]).map(([r,c])=>e.board[r][c]?.id)),marked=new Set((ev.cells||[]).map(([r,c])=>e.board[r][c]?.id)),linked=new Set((ev.groups||[]).flatMap(g=>g.cells.map(([r,c])=>e.board[r][c]?.id))),alive=new Set(),fresh=[];
 if(ev.phase!=='refill'||!animate)stopPour(s);
