 $('title-equip').disabled=!earned||equipped;$('title-equip').onclick=()=>{if(recordBook.equip(selected.id)){updateEquippedTitle();renderRecordMenu();}};
 $('title-unset').disabled=!eq;$('title-unset').onclick=()=>{recordBook.equip(null);updateEquippedTitle();renderRecordMenu();};attachRecordPager(TITLE_DEFS.length,10);
