 $('record-period-all').onclick=()=>{recordPeriod='all';recordOffset=0;renderRecordMenu();};$('record-period-month').onclick=()=>{recordPeriod='month';recordOffset=0;renderRecordMenu();};attachRecordPager(rows.length,5);
