 $('record-menu-layer').addEventListener('keydown',ev=>{if(ev.key==='Escape'){ev.preventDefault();closeRecordMenu();}else if(ev.key==='Tab'){const buttons=[...$('record-menu').querySelectorAll('button,input,select,[tabindex]')].filter(b=>!b.disabled&&!b.hidden&&b.getClientRects().length),first=buttons[0],last=buttons[buttons.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
