let bgmFadeFrame=0,bgmFadeToken=0;
let bgmMediaSource=null,bgmGain=null,bgmLevel=normalBgmVolume;
function connectBgmAudio(){
 if(!audio||bgmMediaSource)return;
 bgmGain=audio.createGain();bgmGain.gain.value=bgmLevel;
 bgmPlayer.connect(audio,bgmGain);bgmMediaSource=bgmPlayer.mediaSource;bgmGain.connect(audio.destination);bgmPlayer.volume=1;
}
function setBgmLevel(value,{fade=false}={}){bgmLevel=fade?Math.max(0,Math.min(1,value)):normalBgmVolume;if(bgmGain){bgmGain.gain.cancelScheduledValues(audio.currentTime);bgmGain.gain.setValueAtTime(bgmLevel,audio.currentTime);}else bgmPlayer.volume=bgmLevel;}
function cancelBgmFade(){bgmFadeToken++;if(bgmFadeFrame)cancelAnimationFrame(bgmFadeFrame);bgmFadeFrame=0;}
