 const old=bgmTransition;bgmTransition=null;if(old){if(old.timer)clearTimeout(old.timer);if(bgmGain&&audio){const now=audio.currentTime;bgmGain.gain.cancelScheduledValues(now);bgmGain.gain.setValueAtTime(bgmLevel,now);}old.resolve(false);}
